class Format(BaseModel):
    # 格式 ID
    format_id: str
    # 容器
    ext: str = ""
    # 高度
    height: int = 0
    # 帧率
    fps: int = 0
    # 体积(MB) 上游没给时为 0
    filesize_mb: float = 0.0


class DownloadIn(BaseModel):
    """Inputs of "下载视频".

    下载后把文件交回平台，画布里流转的是文件引用。**这是重活**：默认超时 15 分钟， 且默认限制 720p / 512MB——不限的话一条 4K 长视频能把磁盘和上传通道占满。"""

    # 视频链接
    url: str
    # 清晰度
    quality: Literal["480", "720", "1080", "best"] = "720"
    # 指定格式 填了就忽略「清晰度」，直接下 video_info 列出的那个 format_id。 很多下载站的「质量列表」就是这么来的：先列上游已有的流，再让你点一个。
    format_id: str = ""
    # 体积上限(MB) 超过就**不下载**、直接报错——比下到一半失败可读得多。**填 0 = 不限**。 平台侧的分块上传本身没有体积上限，真正的天花板是插件容器的磁盘与本操作的超时； 默认给 512 只是因为「不限」意味着第一个粘 4K 长视频链接的人就能把磁盘填满， 而那种故障看起来跟下载毫无关系。
    max_filesize_mb: int = 512
    # 文件名 留空则用视频标题
    filename: str = ""


class DownloadOut(BaseModel):
    """Outputs of "下载视频".

    下载后把文件交回平台，画布里流转的是文件引用。**这是重活**：默认超时 15 分钟， 且默认限制 720p / 512MB——不限的话一条 4K 长视频能把磁盘和上传通道占满。"""

    # 文件
    file: File
    # 标题
    title: str
    # 时长(秒)
    duration_seconds: int
    # 体积(MB)
    filesize_mb: float
    # 容器
    ext: str
    # 规范链接
    webpage_url: str
    # 是否做了合并 高清视频在上游是「视频轨 + 音频轨」两条流，取回来要用 ffmpeg 合并成一个文件 （只是换容器，不重新编码，很快）。360p 及以下上游有单文件版，直接下就行。
    merged: bool


DownloadHandler = Callable[[Ctx, DownloadIn], Union[DownloadOut, Awaitable[Optional[DownloadOut]], None]]


def on_download(p: Plugin, fn: DownloadHandler) -> None:
    """Register the implementation of "下载视频". The handler may be an async def or a plain function."""

    async def _invoke(ctx: Ctx, raw: Dict[str, Any], out: Emitter) -> None:
        res = fn(ctx, DownloadIn.model_validate(raw))
        if inspect.isawaitable(res):
            res = await res
        if res is not None:
            out.vars(res)

    p.register("download", _invoke)


class DownloadAudioIn(BaseModel):
    """Inputs of "下载音频".

    只取音频轨。**默认不转码**——上游的音频本来就是独立的一条流，原样拿下来最快也无损失。 指定 mp3/m4a/opus 时才会用 ffmpeg 转一道（慢一点、且是有损再压一次）。"""

    # 视频链接
    url: str
    # 音频格式
    audio_format: Literal["source", "mp3", "m4a", "opus"] = "source"
    # 码率 只在转码时有意义；原样下载时上游给多少就是多少。
    bitrate: Literal["128", "192", "256", "320"] = "192"
    # 体积上限(MB) 填 0 = 不限。音频通常只有视频的十分之一，很少撞上
    max_filesize_mb: int = 256
    # 文件名 留空则用视频标题
    filename: str = ""


class DownloadAudioOut(BaseModel):
    """Outputs of "下载音频".

    只取音频轨。**默认不转码**——上游的音频本来就是独立的一条流，原样拿下来最快也无损失。 指定 mp3/m4a/opus 时才会用 ffmpeg 转一道（慢一点、且是有损再压一次）。"""

    # 文件
    file: File
    # 标题
    title: str
    # 时长(秒)
    duration_seconds: int
    # 体积(MB)
    filesize_mb: float
    # 容器
    ext: str
    # 编码
    codec: str = ""
    # 是否转过码 true = 经 ffmpeg 重新编码（有损）；false = 上游原始音频轨，逐字节没动过。
    transcoded: bool
    # 规范链接
    webpage_url: str


DownloadAudioHandler = Callable[[Ctx, DownloadAudioIn], Union[DownloadAudioOut, Awaitable[Optional[DownloadAudioOut]], None]]


def on_download_audio(p: Plugin, fn: DownloadAudioHandler) -> None:
    """Register the implementation of "下载音频". The handler may be an async def or a plain function."""

    async def _invoke(ctx: Ctx, raw: Dict[str, Any], out: Emitter) -> None:
        res = fn(ctx, DownloadAudioIn.model_validate(raw))
        if inspect.isawaitable(res):
            res = await res
        if res is not None:
            out.vars(res)

    p.register("download_audio", _invoke)


