class TranscriptIn(BaseModel):
    """Inputs of "抓字幕文本".

    取字幕并转成纯文本（去时间轴、去重复行）。优先人工字幕，没有就用自动生成的。 不下载视频本身，比「下载→转写」快一个数量级，也不花转写的钱。"""

    # 视频链接
    url: str
    # 语言 按 BCP-47 前缀匹配，如 zh / zh-Hans / en；没有该语言时回落到第一个可用字幕
