class TranscriptOut(BaseModel):
    """Outputs of "抓字幕文本".

    取字幕并转成纯文本（去时间轴、去重复行）。优先人工字幕，没有就用自动生成的。 不下载视频本身，比「下载→转写」快一个数量级，也不花转写的钱。"""

    # 字幕文本
    text: str
    # 实际语言
    lang_used: str
    # 是否自动生成 自动字幕有错字，用于摘要可以，用于引用要核对
    automatic: bool
    # 标题
